// <experiment isOn="agentIconSetIds">
/** APIs for resolving Framer module URLs pasted by the user */
interface Modules {
	/**
	 * Resolves a Framer module URL into an insertable component identifier or icon set id
	 * Pass component identifiers as the \`component\` property and icon identifiers as the \`set\` property when inserting nodes
	 * Never insert a raw module URL
	 */
	lookup: (url: string) => Promise<{
		type: "component" | "icon"
		identifier: string
		controls: { controls: Record<string, unknown> } | { error: string }
	}>
}
