// <experiment isOn="harness2">
/** APIs for searching and generating images */
interface Images {
	/** @throws When the image search fails */
	search(options: {
		query: string
		count?: number
		orientation?: "landscape" | "portrait" | "squarish"
		/** Use 2x the width of the frame to be filled. */
		width?: number
	}): Promise<{
		query: string
		results: {
			id: string
			url: string
			smallUrl: string
			alt: string | null
			width: number
			height: number
			color: string
		}[]
	}>
	/**
	 * Resolve \`url\` with \`api.tree.assetReference\` before using it in \`fill\` or other image attributes.
	 * @throws When image generation fails or is not available in this environment
	 */
	generate(prompt: string): Promise<{
		url: string
		smallUrl: string
		width: number
		height: number
		alt: string | null
	}>
}
