async function createEventComponent() {
  const component = tree.insert("ComponentNode", "test-trigger-comp", { parent: tree.root, name: "Test Trigger" });
  const trigger = tree.insert("FrameNode", "fire-btn", {
    parent: component,
    name: "Fire Button",
    htmlTag: "button",
    cursor: "pointer",
    layout: "stack",
    stackDirection: "horizontal",
    stackAlignment: "center",
    stackDistribution: "center",
    gap: "6px",
    padding: "10px 18px",
    width: "auto",
    height: "auto",
    fill: "rgba(239, 68, 68, 1)",
    radius: "8px"
  });
  const event = tree.var({ type: "eventhandler", name: "On Fire" });
  tree.patch(component, { variables: [event] });
  tree.patch(trigger, {
    onTap: [{ action: "TRIGGER_EVENT", controls: { id: tree.ref(event, component) } }]
  });
  tree.insert("RichTextNode", "fire-label", {
    parent: trigger,
    name: "Label",
    text: "Fire",
    width: "auto",
    height: "auto",
    textColor: "rgba(255,255,255,1)"
  });
}
