	// <requires-unlimited-tool-results>
	/**
	 * Request an implementation guidance document by name from Implementation Guidance Documentation Index.
	 * For creation strategy, use during font and guide selection before implementation.
	 * Never read a guide you have previously read.
	 */
	read: (name: string) => Promise<{ name: string; guide: string }>
	/** Automatically attaches an implementation guide to the program result */
	load: (name: string) => void
