interface PublishUrls {
	/** The production URL, when available. */
	production?: string
	/** The staging URL, when staging is enabled. */
	staging?: string
	/** The current branch preview URL, when publishing from a branch. */
	branch?: string
	/** The URL updated by the successful publish or deployment call. */
	published?: string
}

interface PublishDiagnostic {
	/** Human-readable publish issue or warning. */
	title: string
	/** Whether this diagnostic blocks publishing. */
	blocking: boolean
}

interface PublishVersion {
	/** The exact version ID accepted by deployToProduction. */
	id: string
	/** The version creation time as Unix seconds. */
	timestamp: number
	/** The name of the publishing user, when available. */
	publishedBy?: string
}

interface PublishResult {
	/** The destination updated by the successful call. */
	target: "branch" | "staging" | "production"
	/** The exact version created or deployed. */
	version: { id: string }
	/** Recent versions available after the mutation. */
	versions: readonly PublishVersion[]
	/** URLs after the successful mutation; \`published\` is the URL that the call updated. */
	urls: PublishUrls
}

interface EmailFormDestinationPatch {
	type: "email"
	/** Up to 3 recipients (1 on free sites). */
	emails?: readonly (string | null | undefined)[]
	subject?: string
	body?: string
	/** Sender name shown in the notification email */
	name?: string
}

interface WebhookFormDestinationPatch {
	type: "webhook"
	webhookUrl?: string
	/** Used to sign webhook requests */
	secret?: string
	/** Notified when delivery to the webhook fails */
	fallbackEmail?: string
}

type FormDestinationPatch = EmailFormDestinationPatch | WebhookFormDestinationPatch

interface EmailFormDestination {
	type: "email"
	emails: readonly { email: string; verified: boolean }[]
	subject?: string
	body?: string
	name?: string
}

interface WebhookFormDestination {
	type: "webhook"
	webhookUrl?: string
	/** Secrets are never returned; this tells whether one is set */
	hasSecret: boolean
	fallbackEmail?: string
}

interface GoogleSheetFormDestination {
	type: "googlesheet"
	documentName?: string
	fallbackEmail?: string
}

type FormDestination = EmailFormDestination | WebhookFormDestination | GoogleSheetFormDestination
