async function readSitemap() {
  const pathFilter = "";
  const pages = await api.tree.getNodesOfTypes("WebPageNode");
  const sitemap = [];
  for (const page of pages) {
    const { path, draft } = page.attributes || {};
    if (!path) continue;
    if (pathFilter && !path.includes(pathFilter)) continue;
    sitemap.push({
      id: page.id,
      path,
      ...draft ? { draft: true } : {}
    });
  }
  return api.paginate(sitemap);
}
async function readPageOrBreakpoint() {
  const page = await api.tree.getNode("<target-page-or-breakpoint-id>");
  if (!page) return null;
  if (typeof page.$layoutTemplateId !== "string") {
    return page;
  }
  const layoutTemplate = await api.tree.getNode(page.$layoutTemplateId);
  if (!layoutTemplate) {
    return page;
  }
  return {
    page,
    layoutTemplate: await api.serialize(layoutTemplate, { depth: 2 })
  };
}
